//! WPT `mimesniff/media/` and `mimesniff/sniffing/`: the resources those
//! tests serve, with the Content-Type each is served with, as tables of
//! (file, Content-Type, bytes).
//!
//! These WPT tests run in a browser (they load media elements, iframes and
//! popups), so there are no expected outputs to read; the tables carry the
//! inputs, and `tests/conformance_sniffing.rs` states, per WPT test, what
//! the test asserts. What the converter reads:
//! - `media-sniff.window.js`: the `"vectors"` and `"contentTypes"` arrays;
//!   every vector must be vendored.
//! - `mislabeled-binary-resource.tentative.window.js`: the three resources
//!   it loads (each must be named there as `resources/<file>`), with the
//!   Content-Type from the resource's `.headers` file.
//! - `html.window.js`: the `["atom", "rss"]` array it starts with; each
//!   names `support/<item>.html`, which wptserve serves as `text/html` (by
//!   its extension; there is no `.headers` file).

use std::fmt::Write as _;
use std::path::Path;

use super::js::{Parser, find_all};

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &[
    "media-sniff.window.js",
    "flac.flac",
    "mp3-raw.mp3",
    "mp3-with-id3.mp3",
    "mp4.mp4",
    "ogg.ogg",
    "wav.wav",
    "webm.webm",
    "mislabeled-binary-resource.tentative.window.js",
    "binary-data.bin",
    "binary-data.bin.headers",
    "html-content.html",
    "html-content.html.headers",
    "png-image.png",
    "png-image.png.headers",
    "html.window.js",
    "atom.html",
    "rss.html",
];

/// The resources `mislabeled-binary-resource.tentative.window.js` loads
/// and that are vendored. (`test-file.zip` is not: see SOURCE.md.)
const MISLABELED: &[&str] = &["binary-data.bin", "html-content.html", "png-image.png"];

fn read(dir: &Path, file: &str) -> Result<Vec<u8>, String> {
    std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))
}

fn read_text(dir: &Path, file: &str) -> Result<String, String> {
    std::fs::read_to_string(dir.join(file)).map_err(|e| format!("{file}: {e}"))
}

/// The string array right after the only occurrence of `marker` in `file`.
fn strings_after(file: &str, text: &str, marker: &str) -> Result<Vec<String>, String> {
    let node = match find_all(text, marker).as_slice() {
        [pos] => Parser::at(text, *pos).literal(),
        found => Err(format!(
            "expected {marker:?} exactly once, found {} times",
            found.len()
        )),
    }
    .map_err(|e| format!("{file}: {e}"))?;
    node.array()
        .map_err(|e| format!("{file}: {e}"))?
        .iter()
        .map(|n| n.string().map_err(|e| format!("{file}: {e}")))
        .collect()
}

/// The value of the only `Content-Type:` line of a `.headers` file.
fn content_type(file: &str, text: &str) -> Result<String, String> {
    let values: Vec<&str> = text
        .lines()
        .filter_map(|l| l.strip_prefix("Content-Type:"))
        .map(str::trim)
        .collect();
    match values.as_slice() {
        [v] => Ok((*v).to_owned()),
        _ => Err(format!(
            "{file}: expected one Content-Type line, found {}",
            values.len()
        )),
    }
}

fn case(
    out: &mut String,
    file: &str,
    content_type: Option<&str>,
    bytes: &[u8],
) -> Result<(), String> {
    let ct = match content_type {
        Some(c) => format!("Some({c:?})"),
        None => "None".to_owned(),
    };
    let body: Vec<String> = bytes.iter().map(|b| format!("0x{b:02X}")).collect();
    writeln!(
        out,
        "    Case {{ file: {file:?}, content_type: {ct}, bytes: &[{}] }},",
        body.join(", ")
    )
    .map_err(|e| e.to_string())
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let mut out = String::new();
    let w = |out: &mut String, s: &str| writeln!(out, "{s}").map_err(|e| e.to_string());
    w(
        &mut out,
        "// @generated by `cargo xtask testdata` from tests/data/wpt-mimesniff/.",
    )?;
    w(
        &mut out,
        "// Do not edit: `cargo xtask verify` fails if this differs from what the",
    )?;
    w(
        &mut out,
        "// converter (xtask/src/testdata/wpt_mimesniff.rs) produces.",
    )?;
    w(
        &mut out,
        "// Source, commit and license: tests/data/wpt-mimesniff/SOURCE.md.",
    )?;

    // media-sniff.window.js
    let file = "media-sniff.window.js";
    let text = read_text(dir, file)?;
    let vectors = strings_after(file, &text, "\"vectors\": ")?;
    let types = strings_after(file, &text, "\"contentTypes\": ")?;
    if vectors.is_empty() || types.is_empty() {
        return Err(format!("{file}: no vectors or no content types"));
    }
    let quoted: Vec<String> = types.iter().map(|t| format!("{t:?}")).collect();
    w(
        &mut out,
        &format!(
            "/// `{file}`: every vector is served with each of these.\nconst MEDIA_CONTENT_TYPES: &[&str] = &[{}];",
            quoted.join(", ")
        ),
    )?;
    w(
        &mut out,
        &format!("/// `{file}`: the vectors, from `media/resources/`."),
    )?;
    w(&mut out, "const MEDIA: &[Case] = &[")?;
    for v in &vectors {
        if !FILES.contains(&v.as_str()) {
            return Err(format!("{file}: vector {v:?} is not vendored"));
        }
        case(&mut out, v, None, &read(dir, v)?)?;
    }
    w(&mut out, "];")?;

    // mislabeled-binary-resource.tentative.window.js
    let file = "mislabeled-binary-resource.tentative.window.js";
    let text = read_text(dir, file)?;
    w(
        &mut out,
        &format!(
            "/// `{file}`: the resources it loads, from `sniffing/resources/`, with\n/// the Content-Type of their `.headers` file."
        ),
    )?;
    w(&mut out, "const MISLABELED: &[Case] = &[")?;
    for r in MISLABELED {
        if find_all(&text, &format!("'resources/{r}'")).is_empty() {
            return Err(format!("{file}: does not load resources/{r}"));
        }
        let headers = format!("{r}.headers");
        let ct = content_type(&headers, &read_text(dir, &headers)?)?;
        case(&mut out, r, Some(&ct), &read(dir, r)?)?;
    }
    w(&mut out, "];")?;

    // html.window.js
    let file = "html.window.js";
    let text = read_text(dir, file)?;
    let items = Parser::new(&text)
        .literal()
        .and_then(|n| {
            n.array()?
                .iter()
                .map(|i| i.string())
                .collect::<Result<Vec<_>, _>>()
        })
        .map_err(|e| format!("{file}: {e}"))?;
    if find_all(&text, "support/${item}.html").len() != 1 {
        return Err(format!(
            "{file}: expected one window.open(`support/${{item}}.html`)"
        ));
    }
    w(
        &mut out,
        &format!("/// `{file}`: `sniffing/support/<item>.html`, served as text/html."),
    )?;
    w(&mut out, "const FEEDS: &[Case] = &[")?;
    for i in &items {
        let f = format!("{i}.html");
        if !FILES.contains(&f.as_str()) {
            return Err(format!("{file}: {f} is not vendored"));
        }
        case(&mut out, &f, Some("text/html"), &read(dir, &f)?)?;
    }
    w(&mut out, "];")?;
    Ok(out)
}
